 auto select=[&](OPENFILENAMEW* dialog){check(bool(dialog->Flags&OFN_ALLOWMULTISELECT)&&bool(dialog->Flags&OFN_NOCHANGEDIR),"native multi chooser flags");auto put=[&](const std::wstring& part){std::copy(part.begin(),part.end(),dialog->lpstrFile);dialog->lpstrFile+=part.size();*dialog->lpstrFile++=0;};put(root.wstring());put(L"动画.PNG");put(L"cat.mspet");*dialog->lpstrFile=0;return TRUE;};const auto target=root/"saved.mspet";int saveCount=0;auto save=[&](OPENFILENAMEW* dialog){++saveCount;check(std::wstring(dialog->lpstrFile)==L"cat.mspet"&&std::wstring(dialog->lpstrDefExt)==L"mspet"&&(dialog->Flags&OFN_OVERWRITEPROMPT),"save defaults");wcscpy_s(dialog->lpstrFile,dialog->nMaxFile,target.c_str());return TRUE;};FormFiles files(nullptr,select,save);auto input=files.choose(JsonObject{});check(input&&input->size()==2&&(*input)[0].name==L"动画.PNG"&&(*input)[0].mime==L"image/png"&&(*input)[0].bytes==std::vector<std::uint8_t>{'p','n','g'}&&(*input)[1].mime.empty(),"multi read and MIME");check(files.save((*input)[1])&&saveCount==1&&std::filesystem::file_size(target)==3,"atomic save actual file");
