 auto multiPaths=[&](std::vector<std::wstring> names){return FormFiles(nullptr,[&,names](auto* d){auto out=d->lpstrFile;auto put=[&](const std::wstring& v){std::copy(v.begin(),v.end(),out);out+=v.size();*out++=0;};put(root.wstring());for(const auto& name:names)put(name);*out=0;return TRUE;});};
 const auto half=root/"half.png";{std::ofstream f(half,std::ios::binary);f.seekp(8*1024*1024-1);f.put('z');}
